query GetFolder($folderId: ID!) {
    folder(folderId: $folderId) {
        id
        name
        exchanges {
            results {
                id
                name
                alternativeRepresentations {
                    fileUrn
                }
            }
        }
    }
}

query GetFolder($folderId: ID!) {
    folder(folderId: $folderId) {
        id
        name
        exchanges {
            results {
                id
                name
                alternativeRepresentations {
                    fileUrn
                }
            }
        }
        items {
            ... on Items {
                results {
                    id
                    name
                    extensionType
                }
            }
        }
    }
}

query GetPropertyDefinitionOfExchange($exchangeId: ID!) {
    exchange(exchangeId: $exchangeId) {
        id
        name
        propertyDefinitions {
            results {
                id
                name
                units
            }
        }
    }
}

query GetPropertyDefinitionOfExchange($exchangeId: ID!) {
    exchange(exchangeId: $exchangeId) {
        id
        name
        propertyDefinitions {
            results {
                id
                name
                units {
                    name
                }
            }
        }
    }
}
